import std;
import openmui.audio;
int main() {
    omui::audio::Mixer mixer;
    omui::audio::Sound tone{.name="tone", .gain=.1f};
    tone.layers.push_back({.length=1, .envelope={.attack=.01f,.hold=1,.sustain=1,.release=.01f}});
    if (!mixer.play(mixer.add(tone),0)) return 1;
    const auto pcm=omui::audio::render(mixer,48000);
    if (mixer.clock()!=48000 || mixer.begun()!=1 || omui::audio::peak(pcm)<.01f) return 2;
    std::println("audio-only samples={} pcm={:016x}",mixer.clock(),omui::audio::hash(pcm));
}

