import std;
import openmui.audio;
import openmui.timeline;
import openmui.timeline.audio;
import hanim.core;
int main() {
    namespace tl=omui::timeline;
    omui::audio::Mixer mixer;
    tl::Clip clip{.length=tl::from_seconds(1)};
    tl::Property p{.name="gain"};
    p.keys.key(hanim::seconds(0),0).key(hanim::seconds(1),1);
    clip.properties.push_back(std::move(p));
    const auto gain=tl::GainAutomation::prepare(clip,{.sample_rate=mixer.rate(),.outside=0});
    if(!gain || !mixer.automate_gain("music",*gain)) return 1;
    omui::audio::Sound tone{.name="tone", .gain=.1f, .bus="music"};
    tone.layers.push_back({.length=1, .envelope={.attack=.01f,.hold=1,.sustain=1,.release=.01f}});
    if (!mixer.play(mixer.add(tone),0)) return 2;
    const auto pcm=omui::audio::render(mixer,48000);
    if((*gain)->at_sample(24000)!=.5f || mixer.clock()!=48000 || mixer.begun()!=1 || omui::audio::peak(pcm)<.01f) return 3;
    std::println("adapter samples={} pcm={:016x} gain={}",mixer.clock(),omui::audio::hash(pcm),(*gain)->at_sample(24000));
}
